function ringPoints(float $lat,float $lon,float $radius,int $rings=2,int $per=12):array{$out=[[$lat,$lon]];for($r=1;$r<=$rings;$r++){ $count=max(8,$per*$r);for($i=0;$i<$count;$i++){ $a=2*M_PI*$i/$count;[$la,$lo]=destination($lat,$lon,sin($a)*$radius*$r/$rings,cos($a)*$radius*$r/$rings);$out[]=[$la,$lo];}}return$out;}
function pointInPolygon(float $lat,float $lon,array $poly):bool{$inside=false;$n=count($poly);if($n<3)return false;for($i=0,$j=$n-1;$i<$n;$j=$i++){[$yi,$xi]=$poly[$i];[$yj,$xj]=$poly[$j];$cross=(($yi>$lat)!==($yj>$lat))&&($lon<($xj-$xi)*($lat-$yi)/max(1e-15,$yj-$yi)+$xi);if($cross)$inside=!$inside;}return$inside;}
