function truncateTarget(array $tr,?array $target,float $radius,?array $polygon=null):array{if(!$tr)return[];$out=[$tr[0]];for($i=1;$i<count($tr);$i++){ $a=$tr[$i-1];$b=$tr[$i];$hit=$polygon?segmentHitsPolygon([$a['lat'],$a['lon']],[$b['lat'],$b['lon']],$polygon):hav($a['lat'],$a['lon'],$target[0],$target[1])<=$radius||hav($b['lat'],$b['lon'],$target[0],$target[1])<=$radius;if($hit){$out[]=$b;return$out;}$out[]=$b;}return$out;}
function trajectoryMetrics(array $tr,?array $target,float $targetRadius,?array $polygon=null):array{$min=INF;$inside=0.0;$closest=$tr[0]??['time'=>iso(new DateTimeImmutable('now',new DateTimeZone('UTC'))),'lat'=>0,'lon'=>0,'altitude'=>0];for($i=0;$i<count($tr);$i++){if($target){$d=hav($tr[$i]['lat'],$tr[$i]['lon'],$target[0],$target[1]);}else{$d=INF;foreach($polygon??[] as $p)$d=min($d,hav($tr[$i]['lat'],$tr[$i]['lon'],$p[0],$p[1]));if(pointInPolygon($tr[$i]['lat'],$tr[$i]['lon'],$polygon??[]))$d=0;}if($d<$min){$min=$d;$closest=$tr[$i];}if($i>0){$prev=$tr[$i-1];$hit=$target?(hav($tr[$i]['lat'],$tr[$i]['lon'],$target[0],$target[1])<=$targetRadius):(pointInPolygon($tr[$i]['lat'],$tr[$i]['lon'],$polygon??[]));if($hit)$inside+=max(0,utc($tr[$i]['time'])->getTimestamp()-utc($prev['time'])->getTimestamp());}}return[$min,$inside,$closest];}
function surfaceShear(array $fc,float $lat,float $lon,DateTimeImmutable $when,float $top):array{$surface=interp($fc,$lat,$lon,10,$when);$upper=interp($fc,$lat,$lon,max(100,$top),$when);[$e0,$n0]=winduv($surface[0],$surface[1]);[$e1,$n1]=winduv($upper[0],$upper[1]);return[$surface[0],hypot($e1-$e0,$n1-$n0)/max(1,$top-10)];}
function weatherHazard(array $fc,array $tr,float $limit):bool{foreach($tr as $p){$cell=nearestCell($fc,$p['lat'],$p['lon']);$h=$cell['hourly']??[];if(!isset($h['time']))continue;$pt=utc($p['time'])->getTimestamp();$idx=0;$best=INF;foreach($h['time'] as $i=>$tm){$d=abs(utc((string)$tm)->getTimestamp()-$pt);if($d<$best){$best=$d;$idx=$i;}}$code=$h['weather_code'][$idx]??null;$rain=$h['precipitation'][$idx]??0;if(in_array((int)$code,[95,96,99],true)||(float)$rain>$limit)return true;}return false;}
function perturbForecast(array $fc,int $seed,float $sigma):array{mt_srand($seed);$out=$fc;foreach($out['cells'] as &$cell){$h=$cell['hourly']??[];foreach(LEVELS as $p){$k="{$p}hPa";$sk="wind_speed_$k";$dk="wind_direction_$k";if(!isset($h[$sk],$h[$dk]))continue;foreach($h[$sk] as $i=>$speed){if($speed===null||!isset($h[$dk][$i]))continue;[$e,$n]=winduv((float)$speed,(float)$h[$dk][$i]);$e+=gaussian()*$sigma;$n+=gaussian()*$sigma;[$s,$d]=uvwind($e,$n);$h[$sk][$i]=$s;$h[$dk][$i]=$d;}}$cell['hourly']=$h;}unset($cell);mt_srand();return$out;}
function favorable(array $p):array{[$clat,$clon]=parsePoint($p['launch_center']??[],'центра запуска');$target=$p['target']??null;$targetPoly=[];foreach(($p['target_polygon']??[]) as $q)$targetPoly[]=parsePoint($q,'target_polygon');if(!$target&&count($targetPoly)<3)throw new RuntimeException('Укажите target или минимум 3 точки target_polygon.');$targetPt=$target?parsePoint($target,'цели'):null;$ss=utc((string)($p['search_start']??''));$se=utc((string)($p['search_end']??''));if($se<=$ss)throw new RuntimeException('Конец периода должен быть позже начала.');$hours=min(168,max(.01,(float)($p['duration_hours']??4)));$step=max(.5,(float)($p['step_minutes']??2));$timeStep=max(.1,(float)($p['time_step_hours']??1));$launchRadius=max(100,(float)($p['launch_radius_m']??1000));$targetRadius=max(100,(float)($p['target_radius_m']??5000));$surfaceLimit=max(0,(float)($p['surface_wind_limit_mps']??10));$shearLimit=max(0,(float)($p['shear_limit_s_inv']??.002));$rainLimit=max(0,(float)($p['precipitation_limit_mm']??5));$members=max(5,min(150,(int)($p['ensemble_members']??50)));$sigma=max(0,(float)($p['ensemble_wind_sigma_mps']??1.5));$as=max(0,(float)($p['ascent_rate']??5));$maxAlt=max(1000,(float)($p['max_altitude']??8000));$startAlt=max(0,(float)($p['start_altitude']??0));$restricted=[];foreach(($p['restricted_zones']??[]) as $poly){$q=[];foreach($poly as $x)$q[]=parsePoint($x,'restricted_zones');if(count($q)>=3)$restricted[]=$q;}$hazards=[];foreach(($p['hazard_zones']??[]) as $poly){$q=[];foreach($poly as $x)$q[]=parsePoint($x,'hazard_zones');if(count($q)>=3)$hazards[]=$q;}$launches=ringPoints($clat,$clon,$launchRadius,2,12);$windows=[];for($t=$ss;$t<=$se;$t=$t->modify('+'.(int)round($timeStep*3600).' seconds')){$forecastEnd=$t->modify('+'.(int)ceil($hours*3600).' seconds');[$ls,$os]=grid(($clat+($targetPt[0]??$targetPoly[0][0]))/2,($clon+($targetPt[1]??$targetPoly[0][1]))/2,forecastRadius($hours)+$launchRadius/1000);$fc=meteo($ls,$os,$t,$forecastEnd);foreach($launches as $lp){$tr=t