function api():never{$action=$_GET['api']??'';if($_SERVER['REQUEST_METHOD']==='GET'){if($action==='health')json_out(['status'=>'ok','service'=>'weter-timeweb','version'=>'2.0']);if($action==='config')json_out(['max_trajectory_hours'=>168,'default_step_minutes'=>5,'backtrajectory'=>['ensemble'=>true,'correlated_wind_bias'=>true,'observation_uncertainty'=>true],'favorable'=>['ensemble'=>true,'surface_wind_filter'=>true,'wind_shear_filter'=>true,'weather_hazard_filter'=>true,'restricted_zones'=>true,'target_polygon'=>true,'ensemble_p90'=>true,'background_jobs'=>false,'provider'=>'Open-Meteo']]);if($action==='wind'){try{$lat=(float)($_GET['lat']??0);$lon=(float)($_GET['lon']??0);$alt=(float)($_GET['altitude']??1000);$now=new DateTimeImmutable('now',new DateTimeZone('UTC'));[$ls,$os]=grid($lat,$lon,150);$fc=meteo($ls,$os,$now,$now->modify('+1 day'));[$speed,$dir]=interp($fc,$lat,$lon,$alt,$now);json_out(['lat'=>$lat,'lon'=>$lon,'altitude'=>$alt,'wind_speed'=>$speed,'wind_direction'=>$dir,'time'=>iso($now)]);}catch(Throwable $e){fail('Weather provider error: '.substr($e->getMessage(),0,500),502);}}fail('API endpoint');}$p=req();try{if($action==='trajectory'){[$lat,$lon]=parsePoint($p['start']??[],'старта');$st=utc((string)$p['start_time']);$hours=min(168,max(.01,(float)($p['duration_hours']??24)));$end=$st->modify('+'.(int)ceil($hours*3600).' seconds');[$ls,$os]=grid($lat,$lon,forecastRadius($hours));$fc=meteo($ls,$os,$st,$end);$tr=traj(['lat'=>$lat,'lon'=>$lon,'start_time'=>iso($st),'start_altitude'=>(float)($p['start_altitude']??0),'ascent_rate'=>(float)($p['ascent_rate']??5),'max_altitude'=>(float)($p['max_altitude']??10000),'duration_hours'=>$hours,'step_minutes'=>(float)($p['step_minutes']??5)],$fc);json_out(['status'=>'ok','trajectory'=>$tr,'points'=>$tr]);}if($action==='backtrajectory'){[$dlat,$dlon]=parsePoint($p['detection']??[],'обнаружения');$dt=utc((string)$p['detection_time']);$hours=min(48,max(.01,(float)($p['duration_hours']??4)));$step=max(1,(float)($p['step_minutes']??1));$alt=max(0,(float)($p['altitude']??0));$start=$dt->modify('-'.(int)ceil($hours*3600).' seconds');[$ls,$os]=grid($dlat,$dlon,forecastRadius($hours));$fc=meteo($ls,$os,$start,$dt);$members=max(20,min(500,(int)($p['members']??150)));$ens=backEnsemble($fc,$dlat,$dlon,$alt,$dt,$hours,$step,(float)($p['ascent_rate']??5),$members,(float)($p['wind_sigma_mps']??1.5),(float)($p['detection_time_sigma_s']??60),(float)($p['altitude_sigma_m']??50));$tr=$ens['trajectories'][0]??[];json_out(['status'=>'ok','result'=>['detection'=>['lat'=>$dlat,'lon'=>$dlon,'altitude'=>$alt,'time'=>iso($dt)],'launch_estimate'=>$ens['launch_estimate'],'zones'=>$ens['zones'],'ensemble_size'=>$ens['ensemble_size'],'valid_members'=>$ens['valid_members'],'trajectories'=>$ens['trajectories'],'trajectory'=>$tr,'points'=>$tr]]);}if($action==='favorable')json_out(favorable($p));if($action==='favorable/start')json_out(['status'=>'accepted','job_id'=>'sync-'.bin2hex(random_bytes(8))],202);if(str_starts_with($action,'favorable/status/'))json_out(['status'=>'error','error'=>'Фоновый режим недоступен на обычном PHP-хостинге; используйте /?api=favorable']);fail('Неизвестный API метод',404);}catch(ValueError|RuntimeException $e){fail($e->getMessage(),422);}catch(Throwable $e){fail('Ошибка сервера: '.substr($e->getMessage(),0,500),502);}}
